function renderCodeHoldings(){
const grid=$('codeHoldingsGrid');if(!grid)return;
grid.innerHTML=CODE_HOLDINGS.map(p=>'<article id="code-holding-'+p.id+'" tabindex="-1" aria-labelledby="code-title-'+p.id+'" class="card-line rounded-2xl bg-panel p-6 card-hover flex flex-col">'
+'<div class="font-mono text-[10px] tracking-[.16em] text-emerald-300">'+p.category+'</div>'
+'<h3 id="code-title-'+p.id+'" class="font-bold text-xl mt-3">'+p.name+'</h3>'
+'<p class="text-mute text-sm leading-relaxed mt-3">'+p.summary+'</p>'
+'<div class="card-line rounded-xl bg-black/30 p-4 mt-4"><div class="font-mono text-[9px] tracking-widest text-lime mb-2">POTENTIAL IP ROUTE</div><p class="text-sm leading-relaxed">'+p.potential+'</p></div>'
+'<div class="mt-4 space-y-3"><div><div class="font-mono text-[9px] tracking-widest text-amber-300 mb-1">RIGHTS SIGNAL</div><p class="text-[11px] text-mute leading-relaxed">'+p.rights+'</p></div><div><div class="font-mono text-[9px] tracking-widest text-mute mb-1">STATUS / DILIGENCE</div><p class="text-[11px] text-mute leading-relaxed">'+p.status+'</p></div></div>'
+'<div class="mt-auto pt-5 flex flex-wrap gap-2"><a href="'+p.repo+'" target="_blank" rel="noopener noreferrer" class="btn-ghost rounded-lg px-3 py-2 text-[11px] font-mono">SOURCE REPO ↗</a>'
+(p.demo?'<a href="'+p.demo+'" target="_blank" rel="noopener noreferrer" class="btn-lime rounded-lg px-3 py-2 text-[11px] font-mono font-bold">LIVE DEMO ↗</a>':'')+'</div></article>').join('');
}
function openCodeHolding(id){scrollToId('software-ip');requestAnimationFrame(()=>{const card=$('code-holding-'+id);if(card){card.scrollIntoView({behavior:'smooth',block:'center'});card.focus({preventScroll:true})}})}
