function toast(msg){const d=document.createElement('div');d.className='toast-in glass border border-lime/40 rounded-xl px-4 py-3 text-sm flex gap-2 items-start';d.innerHTML='<span class="text-lime">●</span><span>'+msg+'</span>';$('toasts').appendChild(d);setTimeout(()=>{d.style.opacity='0';d.style.transition='.4s';setTimeout(()=>d.remove(),400)},3200)}
function openModal(html){$('modalBox').innerHTML=html;$('modalOverlay').classList.remove('hidden');$('modalOverlay').classList.add('flex');document.body.style.overflow='hidden'}
function closeModal(){$('modalOverlay').classList.add('hidden');$('modalOverlay').classList.remove('flex');document.body.style.overflow=''}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closePalette();toggleCart(false)}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette()}});

