/* ============ AUDIO ENGINE ============ */
let AC=null;function ac(){if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();return AC}
function noiseBuf(dur){const c=ac(),b=c.createBuffer(1,c.sampleRate*dur,c.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;return b}
function env(g,t,a,peak,dec){g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(peak,t+a);g.gain.exponentialRampToValueAtTime(.0001,t+a+dec)}
function drum(type,when){const c=ac(),t=when||c.currentTime;
if(type==='kick'){const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(160,t);o.frequency.exponentialRampToValueAtTime(42,t+.12);env(g,t,.002,.9,.28);o.connect(g).connect(c.destination);o.start(t);o.stop(t+.35)}
else if(type==='snare'){const n=c.createBufferSource();n.buffer=noiseBuf(.2);const f=c.createBiquadFilter();f.type='bandpass';f.frequency.value=1800;const g=c.createGain();env(g,t,.001,.6,.18);n.connect(f).connect(g).connect(c.destination);n.start(t);const o=c.createOscillator(),g2=c.createGain();o.frequency.value=190;env(g2,t,.001,.5,.1);o.connect(g2).connect(c.destination);o.start(t);o.stop(t+.15)}
else if(type==='hat'){const n=c.createBufferSource();n.buffer=noiseBuf(.08);const f=c.createBiquadFilter();f.type='highpass';f.frequency.value=7500;const g=c.createGain();env(g,t,.001,.35,.06);n.connect(f).connect(g).connect(c.destination);n.start(t)}
else if(type==='perc'){const o=c.createOscillator(),g=c.createGain();o.type='square';o.frequency.setValueAtTime(300+Math.random()*600,t);o.frequency.exponentialRampToValueAtTime(90,t+.09);env(g,t,.001,.3,.1);const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=2400;o.connect(f).connect(g).connect(c.destination);o.start(t);o.stop(t+.14)}
else if(type==='clap'){for(let i=0;i<3;i++){const n=c.createBufferSource();n.buffer=noiseBuf(.05);const f=c.createBiquadFilter();f.type='bandpass';f.frequency.value=2200;const g=c.createGain();env(g,t+i*.02,.001,.4,.08);n.connect(f).connect(g).connect(ac().destination);n.start(t+i*.02)}}
else if(type==='zap'){const o=c.createOscillator(),g=c.createGain();o.type='sawtooth';o.frequency.setValueAtTime(2200,t);o.frequency.exponentialRampToValueAtTime(120,t+.15);env(g,t,.001,.25,.16);o.connect(g).connect(c.destination);o.start(t);o.stop(t+.2)}
else if(type==='bloop'){const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(400,t);o.frequency.exponentialRampToValueAtTime(1200,t+.1);o.frequency.exponentialRampToValueAtTime(200,t+.25);env(g,t,.005,.4,.3);o.connect(g).connect(c.destination);o.start(t);o.stop(t+.35)}
else if(type==='gore'){const o=c.createOscillator(),g=c.createGain();o.type='sawtooth';o.frequency.setValueAtTime(70,t);o.frequency.linearRampToValueAtTime(45,t+.4);const l=c.createOscillator(),lg=c.createGain();l.frequency.value=9;lg.gain.value=30;l.connect(lg).connect(o.frequency);env(g,t,.01,.5,.5);const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=500;o.connect(f).connect(g).connect(c.destination);o.start(t);l.start(t);o.stop(t+.6);l.stop(t+.6)}}
function previewSFX(id){ac();if(id==='micro'){drum('zap');setTimeout(()=>drum('hat'),90);setTimeout(()=>drum('perc'),180)}else if(id==='bio'){drum('bloop');setTimeout(()=>drum('bloop'),220)}else if(id==='unholy'){drum('gore')}else{drum('perc');setTimeout(()=>drum('perc'),150)}toast('Previewing pack audio (synthesized live)')}

